  const raw=await database(page);await open();await expect(page.getByTestId('configuration-dialog')).toContainText('无需灵石、丹药或游戏岁月');await frame(page,info,'configuration-'+action.type+'-comparison');expect(await snapshot(page)).toEqual(current);expect(await database(page)).toEqual(raw);await page.getByTestId('configuration-cancel').click();expect(await snapshot(page)).toEqual(current);expect(await database(page)).toEqual(raw);await noArrival(page);await open();
  // A failed explicit intent is discarded by cancel; the later confirmation is a new authorization.
  await page.evaluate(()=>{const t=window as any,put=IDBObjectStore.prototype.put;t.__equipmentRestorePut=()=>IDBObjectStore.prototype.put=put;IDBObjectStore.prototype.put=function(value:any,key?:IDBValidKey){if(this.transaction.db.name==='chenyuan-playable-v1'&&this.name==='full-receipts'&&value?.format==='chenyuan-configuration-receipt'){t.__equipmentRejectedConfiguration=structuredClone(value.intent);t.__equipmentRestorePut();throw new DOMException('ART03 cancelled configuration quota','QuotaExceededError');}return put.call(this,value,key!);};});
